  const calculate = () => quoteGymMembership(session.token, gymId, planId).then(setQuote).catch((err) => setError(err.message));
  if (!gym) return <View style={styles.detailPage}><Pressable onPress={onBack}><Text style={styles.backText}>← Back</Text></Pressable>{error ? <Text style={styles.communityError}>{error}</Text> : <ActivityIndicator color={colors.primary} style={styles.feedLoading} />}</View>;
