function QuoteCard({ quote, paymentLabel }) { return <View style={styles.quoteCard}><Text style={styles.listHeading}>{quote.ticket?.name || quote.plan?.name}</Text><View style={styles.quoteRow}><Text style={styles.eventMeta}>Subtotal</Text><Text style={styles.quoteValue}>₹{quote.subtotal}</Text></View>{quote.platformFee !== undefined && <View style={styles.quoteRow}><Text style={styles.eventMeta}>Platform fee</Text><Text style={styles.quoteValue}>₹{quote.platformFee}</Text></View>}<View style={styles.quoteRow}><Text style={styles.eventMeta}>Tax</Text><Text style={styles.quoteValue}>₹{quote.tax}</Text></View><View style={styles.quoteTotal}><Text style={styles.ticketName}>Total</Text><Text style={styles.quoteTotalValue}>₹{quote.total}</Text></View><View style={styles.paymentNotice}><Text style={styles.eventMeta}>{paymentLabel}. The quote is live; no payment is created yet.</Text></View></View>; }

function AICoachScreen({ session }) {
  const messageListRef = useRef(null);
  return <CoachConversation session={session} />;
  const [messages, setMessages] = useState([{ role: 'coach', text: `Hi ${session.user?.name?.split(' ')[0] || 'Athlete'} — I’m your RepUps AI Coach. What would you like to work on today?` }]); const [text, setText] = useState(''); const [sending, setSending] = useState(false);
  const send = async (prompt = text) => { const query = prompt.trim(); if (!query || sending) return; setText(''); setMessages((items) => [...items, { role: 'user', text: query }]); setSending(true); try { const response = await chatWithCoach(session.token, query); setMessages((items) => [...items, { role: 'coach', text: response.reply || response.message || 'I could not generate a response.' }]); } catch (error) { setMessages((items) => [...items, { role: 'coach', error: true, text: error.message }]); } finally { setSending(false); } };
  const suggestions = ['Improve my posture', 'Plan today’s workout', 'Recovery advice'];
  return <View style={styles.coachPage}><View style={styles.coachHeader}><View><Text style={styles.communityTitle}>AI Coach</Text><Text style={styles.coachStatus}>● Online · Personal training assistant</Text></View><View style={styles.coachBadge}><Text style={styles.coachBadgeText}>AI</Text></View></View><View style={styles.chatArea}>{messages.map((message, index) => <View key={`${message.role}-${index}`} style={[styles.chatBubble, message.role === 'user' ? styles.userBubble : styles.coachBubble, message.error && styles.errorBubble]}><Text style={[styles.chatText, message.role === 'user' && styles.userChatText]}>{message.text}</Text></View>)}{sending && <View style={[styles.chatBubble, styles.coachBubble]}><ActivityIndicator size="small" color={colors.primary} /></View>}</View><Text style={styles.suggestionLabel}>ASK YOUR COACH</Text><View style={styles.suggestions}>{suggestions.map((item) => <Pressable key={item} disabled={sending} onPress={() => send(item)} style={styles.suggestion}><Text style={styles.suggestionText}>{item}</Text></Pressable>)}</View><View style={styles.chatInputRow}><TextInput value={text} onChangeText={setText} placeholder="Message your coach…" placeholderTextColor={colors.muted} style={styles.chatInput} multiline /><Pressable disabled={!text.trim() || sending} onPress={() => send()} style={[styles.chatSend, (!text.trim() || sending) && styles.disabled]}><Text style={styles.chatSendText}>↑</Text></Pressable></View></View>;
}

function CoachConversation({ session }) {
  const [messages, setMessages] = useState([{ role: 'coach', text: `Hi ${session.user?.name?.split(' ')[0] || 'Athlete'} — I’m your RepUps AI Coach. What would you like to work on today?` }]);
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);
  const scrollRef = useRef(null);
  const scrollToLatest = () => setTimeout(() => scrollRef.current?.scrollToEnd({ animated: true }), 80);
  useEffect(() => { scrollToLatest(); }, [messages, sending]);
  const send = async (prompt = text) => {
    const query = prompt.trim();
    if (!query || sending) return;
    setText('');
    setMessages((items) => [...items, { role: 'user', text: query }]);
    setSending(true);
    try {
      const response = await chatWithCoach(session.token, query);
      setMessages((items) => [...items, { role: 'coach', text: response.reply || response.message || 'I could not generate a response.' }]);
    } catch (error) {
      setMessages((items) => [...items, { role: 'coach', error: true, text: error.message }]);
    } finally { setSending(false); }
  };
  return <KeyboardAvoidingView style={styles.coachKeyboard} behavior={Platform.OS === 'ios' ? 'padding' : 'height'} keyboardVerticalOffset={0}>
    <View style={styles.coachHeader}><View><Text style={styles.communityTitle}>AI Coach</Text><Text style={styles.coachStatus}>● Online · Personal training assistant</Text></View><View style={styles.coachBadge}><Text style={styles.coachBadgeText}>AI</Text></View></View>
    <ScrollView ref={scrollRef} style={styles.coachMessages} contentContainerStyle={styles.coachMessagesContent} keyboardShouldPersistTaps="handled" onContentSizeChange={scrollToLatest}>{messages.map((message, index) => <View key={`${message.role}-${index}`} style={[styles.chatBubble, message.role === 'user' ? styles.userBubble : styles.coachBubble, message.error && styles.errorBubble]}><Text style={[styles.chatText, message.role === 'user' && styles.userChatText]}>{message.text}</Text></View>)}{sending && <View style={[styles.chatBubble, styles.coachBubble]}><ActivityIndicator size="small" color={colors.primary} /></View>}</ScrollView>
    <Text style={styles.suggestionLabel}>ASK YOUR COACH</Text><View style={styles.suggestions}>{['Improve my posture', 'Plan today’s workout', 'Recovery advice'].map((item) => <Pressable key={item} disabled={sending} onPress={() => send(item)} style={styles.suggestion}><Text style={styles.suggestionText}>{item}</Text></Pressable>)}</View>
    <View style={styles.chatInputRow}><TextInput value={text} onChangeText={setText} placeholder="Message your coach…" placeholderTextColor={colors.muted} style={styles.chatInput} multiline onFocus={scrollToLatest} /><Pressable disabled={!text.trim() || sending} onPress={() => send()} style={[styles.chatSend, (!text.trim() || sending) && styles.disabled]}><Text style={styles.chatSendText}>↑</Text></Pressable></View>
  </KeyboardAvoidingView>;
}

function TrainerDiscoveryScreen({ session }) {
  const [trainers, setTrainers] = useState([]); const [query, setQuery] = useState(''); const [location, setLocation] = useState(''); const [specialization, setSpecialization] = useState('All'); const [showFilters, setShowFilters] = useState(false); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [selected, setSelected] = useState(null); const [maxDistance, setMaxDistance] = useState(30);
  const load = (value = '') => { setLoading(true); getClientTrainers(session.token, value).then(setTrainers).catch((err) => setError(err.message)).finally(() => setLoading(false)); };
  useEffect(() => { load(); }, [session.token]);
  const specializations = ['All', ...new Set(trainers.flatMap((trainer) => trainer.specializations || []).map((item) => String(item?.name || item)).filter(Boolean))];
  const visible = trainers.filter((trainer) => { const specialties = (trainer.specializations || []).map((item) => String(item?.name || item).toLowerCase()); const matchesSpecialty = specialization === 'All' || specialties.includes(specialization.toLowerCase()); const place = `${trainer.location || ''} ${trainer.locationName || ''} ${trainer.city || ''} ${trainer.gym || ''}`.toLowerCase(); const matchesLocation = !location.trim() || place.includes(location.trim().toLowerCase()); const matchesDistance = trainer.distanceKm !== undefined ? trainer.distanceKm <= maxDistance : true; return matchesSpecialty && matchesLocation && matchesDistance; });
  if (selected) return <TrainerProfileScreen session={session} trainerId={selected} onBack={() => setSelected(null)} />;
  return <View style={styles.trainersPage}><Text style={styles.communityTitle}>Find your trainer</Text><Text style={styles.communitySubtitle}>{visible.length} trainer{visible.length === 1 ? '' : 's'} available</Text><View style={styles.trainerSearch}><TextInput value={query} onChangeText={setQuery} onSubmitEditing={() => load(query)} placeholder="Search trainers or specialties…" placeholderTextColor={colors.muted} style={styles.trainerSearchInput} /><Pressable onPress={() => load(query)} style={styles.searchButton}><Text style={styles.searchButtonText}>Search</Text></Pressable></View><Pressable onPress={() => setShowFilters((value) => !value)} style={[styles.filterToggle, showFilters && styles.filterToggleActive]}><Text style={[styles.filterToggleText, showFilters && styles.filterToggleTextActive]}>☷ Filters {specialization !== 'All' || location ? '• Active' : ''}</Text></Pressable>{showFilters && <View style={styles.filterPanel}><Text style={styles.fieldLabel}>LOCATION</Text><TextInput value={location} onChangeText={setLocation} placeholder="City, gym, or area" placeholderTextColor={colors.muted} style={styles.filterTextInput} /><Text style={styles.fieldLabel}>DISTANCE</Text><View style={{ flexDirection: 'row', alignItems: 'center', gap: 10, marginBottom: 8 }}><Text style={{ color: colors.text, fontSize: 11, fontWeight: '700', minWidth: 60 }}>Within {maxDistance} km</Text><Slider style={{ flex: 1 }} minimumValue={1} maximumValue={30} value={maxDistance} onValueChange={(val) => setMaxDistance(Math.round(val))} minimumTrackTintColor={colors.primary} maximumTrackTintColor={colors.border} thumbTintColor={colors.primary} /><Text style={{ color: colors.muted, fontSize: 9 }}>1 km</Text><Text style={{ color: colors.muted, fontSize: 9 }}>30 km</Text></View><Text style={styles.fieldLabel}>SPECIALIZATION</Text><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.filterChips}>{specializations.map((item) => <Pressable key={item} onPress={() => setSpecialization(item)} style={[styles.filterChip, specialization === item && styles.filterChipActive]}><Text style={[styles.filterChipText, specialization === item && styles.filterChipTextActive]}>{item}</Text></Pressable>)}</ScrollView><Pressable onPress={() => { setLocation(''); setSpecialization('All'); setMaxDistance(30); }}><Text style={styles.clearFilters}>Clear filters</Text></Pressable></View>}{loading ? <ActivityIndicator color={colors.primary} style={styles.feedLoading} /> : error ? <Text style={styles.communityError}>{error}</Text> : visible.length === 0 ? <Text style={styles.emptyFeed}>No trainers match these filters.</Text> : visible.map((trainer) => <Pressable key={trainer._id} onPress={() => setSelected(trainer._id)} style={styles.trainerCard}><View style={styles.trainerAvatar}><Text style={styles.trainerAvatarText}>{(trainer.name || '?').split(' ').map((part) => part[0]).slice(0, 2).join('').toUpperCase()}</Text></View><View style={styles.trainerContent}><Text style={styles.trainerName}>{trainer.name}</Text><Text style={styles.trainerTitle}>{trainer.title || trainer.email}</Text><View style={styles.tagRow}>{(trainer.specializations || []).slice(0, 3).map((tag) => <Text key={tag?.name || tag} style={styles.trainerTag}>{tag?.name || tag}</Text>)}</View><Text style={styles.trainerAvailability}>{trainer.online ? '● Available now' : 'View profile'}</Text></View><Text style={styles.chevron}>›</Text></Pressable>)}</View>;
}

