export default function App() {
  const [session, setSession] = useState(undefined);
  useEffect(() => { getSession().then(setSession); }, []);
  if (session === undefined) return <SafeAreaView style={styles.loading}><ActivityIndicator color={colors.primary} /></SafeAreaView>;
  if (!session) return <AuthScreen onAuthenticated={setSession} />;
  return <Dashboard session={session} onSignOut={async () => { await clearSession(); setSession(null); }} />;
}

